            if (!strcmp(opt, "-column"))  { st.mode = MODE_COLUMN; continue; }
            if (!strcmp(opt, "-csv"))     { st.mode = MODE_CSV;    strcpy(st.colSep,","); continue; }
            if (!strcmp(opt, "-html"))    { st.mode = MODE_HTML;   continue; }
            if (!strcmp(opt, "-json"))    { st.mode = MODE_JSON;   continue; }
            if (!strcmp(opt, "-line"))    { st.mode = MODE_LINE;   continue; }
            if (!strcmp(opt, "-list"))    { st.mode = MODE_LIST;   continue; }
            if (!strcmp(opt, "-markdown")){ st.mode = MODE_MARKDOWN; continue; }
            if (!strcmp(opt, "-quote"))   { st.mode = MODE_QUOTE;  continue; }
            if (!strcmp(opt, "-table"))   { st.mode = MODE_TABLE;  continue; }
            if (!strcmp(opt, "-tabs"))    { st.mode = MODE_TABS;   strcpy(st.colSep,"\t"); continue; }
            if (needsArg(opt)) {
                if (i + 1 >= argc) {
