    /* Open the database */
    sqlite3 *db = NULL;
    const char *openName = dbfile ? dbfile : ":memory:";
    if (sqlite3_open(openName, &db) != SQLITE_OK) {
        fprintf(stderr, "Error: unable to open database \"%s\": %s\n",
                openName, sqlite3_errmsg(db));
        if (db) sqlite3_close(db);
        return 1;
    }

    int exitCode = 0;

    /* Run SQL command-line arguments */
    for (int k = 0; k < nSqlArgs; k++) {
        if (st.echo) { fputs(sqlArgs[k], stdout); fputc('\n', stdout); }
