/*
** Minimal reimplementation of the SQLite command-line shell (sqlite3).
** Uses the system libsqlite3 as the SQL engine; implements the CLI on top.
*/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <ctype.h>
#include <unistd.h>

/* ---- Minimal SQLite C API declarations ---- */
typedef struct sqlite3 sqlite3;
typedef struct sqlite3_stmt sqlite3_stmt;
typedef long long sqlite3_int64;

extern int   sqlite3_open(const char *filename, sqlite3 **ppDb);
extern int   sqlite3_close(sqlite3 *);
extern int   sqlite3_prepare_v2(sqlite3 *db, const char *zSql, int nByte,
                                sqlite3_stmt **ppStmt, const char **pzTail);
extern int   sqlite3_step(sqlite3_stmt*);
extern int   sqlite3_reset(sqlite3_stmt *pStmt);
extern int   sqlite3_column_count(sqlite3_stmt *pStmt);
extern const char *sqlite3_column_name(sqlite3_stmt*, int N);
extern int   sqlite3_column_type(sqlite3_stmt*, int iCol);
extern const unsigned char *sqlite3_column_text(sqlite3_stmt*, int iCol);
extern const void *sqlite3_column_blob(sqlite3_stmt*, int iCol);
extern int   sqlite3_column_bytes(sqlite3_stmt*, int iCol);
extern double sqlite3_column_double(sqlite3_stmt*, int iCol);
extern sqlite3_int64 sqlite3_column_int64(sqlite3_stmt*, int iCol);
extern int   sqlite3_finalize(sqlite3_stmt *pStmt);
extern const char *sqlite3_errmsg(sqlite3*);
extern int   sqlite3_extended_errcode(sqlite3 *db);
extern int   sqlite3_errcode(sqlite3 *db);
extern int   sqlite3_error_offset(sqlite3 *db);
extern int   sqlite3_complete(const char *sql);

#define SQLITE_OK       0
#define SQLITE_ERROR    1
#define SQLITE_ROW      100
#define SQLITE_DONE     101
#define SQLITE_INTEGER  1
#define SQLITE_FLOAT    2
#define SQLITE_TEXT     3
#define SQLITE_BLOB     4
#define SQLITE_NULL     5

/* Version information matching the target executable */
static const char *kVersionString =
    "3.54.0 2026-04-14 20:02:49 "
    "49b3bac482c831f503c7f90c35959e7ea731950e991baba86b2ab95987d2539b "
    "(64-bit)\n";

static const char *kHelpText =
"Usage: %s [OPTIONS] [FILENAME [SQL...]]\n"
"FILENAME is the name of an SQLite database. A new database is created\n"
"if the file does not previously exist. Defaults to :memory:.\n"
"OPTIONS include:\n"
"   --                   treat no subsequent arguments as options\n"
"   -A ARGS...           run \".archive ARGS\" and exit\n"
"   -append              append the database to the end of the file\n"
"   -ascii               set output mode to 'ascii'\n"
"   -bail                stop after hitting an error\n"
"   -batch               force batch I/O\n"
"   -box                 set output mode to 'box'\n"
"   -cmd COMMAND         run \"COMMAND\" before reading stdin\n"
"   -column              set output mode to 'column'\n"
"   -csv                 set output mode to 'csv'\n"
"   -deserialize         open the database using sqlite3_deserialize()\n"
"   -echo                print inputs before execution\n"
"   -escape T            ctrl-char escape; T is one of: symbol, ascii, off\n"
"   -init FILENAME       read/process named file\n"
"   -[no]header          turn headers on or off\n"
"   -help                show this message\n"
"   -html                set output mode to HTML\n"
"   -ifexists            only open if database already exists\n"
"   -interactive         force interactive I/O\n"
"   -json                set output mode to 'json'\n"
"   -line                set output mode to 'line'\n"
"   -list                set output mode to 'list'\n"
"   -lookaside SIZE N    use N entries of SZ bytes for lookaside memory\n"
"   -markdown            set output mode to 'markdown'\n"
"   -maxsize N           maximum size for a --deserialize database\n"
"   -memtrace            trace all memory allocations and deallocations\n"
"   -mmap N              default mmap size set to N\n"
"   -newline SEP         set output row separator. Default: '\\n'\n"
"   -nofollow            refuse to open symbolic links to database files\n"
"   -noinit              Do not read the ~/.sqliterc file at startup\n"
"   -nonce STRING        set the safe-mode escape nonce\n"
"   -no-rowid-in-view    Disable rowid-in-view using sqlite3_config()\n"
"   -nullvalue TEXT      set text string for NULL values. Default ''\n"
"   -pagecache SIZE N    use N slots of SZ bytes each for page cache memory\n"
"   -pcachetrace         trace all page cache operations\n"
"   -quote               set output mode to 'quote'\n"
"   -readonly            open the database read-only\n"
"   -safe                enable safe-mode\n"
"   -screenwidth N       use N as the default screenwidth \n"
"   -separator SEP       set output column separator. Default: '|'\n"
"   -stats               print memory stats before each finalize\n"
"   -table               set output mode to 'table'\n"
"   -tabs                set output mode to 'tabs'\n"
"   -unsafe-testing      allow unsafe commands and modes for testing\n"
"   -version             show SQLite version\n"
"   -vfs NAME            use NAME as the default VFS\n"
"   -vfstrace            enable tracing of all VFS calls\n"
"   -zip                 open the file as a ZIP Archive\n";

/* ---- Output modes ---- */
enum {
    MODE_LIST = 0,
    MODE_LINE,
    MODE_CSV,
    MODE_TABS,
    MODE_HTML,
    MODE_JSON,
    MODE_ASCII,
    MODE_QUOTE,
    MODE_MARKDOWN,
    MODE_TABLE,
    MODE_BOX,
    MODE_COLUMN
};

/* ---- Shell state ---- */
typedef struct ShellState {
    int  mode;
    int  showHeader;
    int  echo;
    int  bail;
    char colSep[64];
    char rowSep[64];
    char nullValue[64];
    int  argOrdinal; /* 1-based index of the arg being executed */
    char *progName;
} ShellState;

static void initShell(ShellState *p) {
    memset(p, 0, sizeof(*p));
    p->mode = MODE_LIST;
    p->showHeader = 0;
    p->echo = 0;
    p->bail = 0;
    strcpy(p->colSep, "|");
    strcpy(p->rowSep, "\n");
    strcpy(p->nullValue, "");
    p->argOrdinal = 0;
}

/* Return ordinal suffix string */
static const char *ordinalSuffix(int n) {
    int mod100 = n % 100;
    int mod10  = n % 10;
    if (mod100 >= 11 && mod100 <= 13) return "th";
    switch (mod10) {
        case 1: return "st";
        case 2: return "nd";
        case 3: return "rd";
        default: return "th";
    }
}

/* Output an SQL parse error (matching sqlite3 CLI format). */
static void outputSqlError(ShellState *p, sqlite3 *db, const char *sql,
                           int argIndex, int isCmdline)
{
    const char *msg = sqlite3_errmsg(db);
    int off = sqlite3_error_offset(db);
    if (isCmdline) {
        fprintf(stderr, "Parse error in %d%s command line argument: %s\n",
                argIndex, ordinalSuffix(argIndex), msg);
    } else {
        fprintf(stderr, "Parse error near line 1: %s\n", msg);
    }
    if (sql) {
        /* Print the offending SQL with ^--- pointer */
        const char *line = sql;
        /* strip trailing newlines for display */
        int len = strlen(line);
        while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) len--;
        fprintf(stderr, "  %.*s\n", len, line);
        if (off >= 0 && off <= len) {
            fprintf(stderr, "  ");
            for (int i = 0; i < off; i++) fputc(' ', stderr);
            fprintf(stderr, "^--- error here\n");
        }
    }
}

/* CSV field output - quote if contains special chars */
static void csvOutputField(FILE *out, const char *s, const char *sep) {
    int needsQuote = 0;
    const char *p;
    if (s == NULL) { return; }
    for (p = s; *p; p++) {
        if (*p == '"' || *p == '\n' || *p == '\r') { needsQuote = 1; break; }
        if (strchr(sep, *p)) { needsQuote = 1; break; }
    }
    if (needsQuote) {
        fputc('"', out);
        for (p = s; *p; p++) {
            if (*p == '"') fputc('"', out);
            fputc(*p, out);
        }
        fputc('"', out);
    } else {
        fputs(s, out);
    }
}

/* HTML escape output */
static void htmlOutputField(FILE *out, const char *s) {
    for (const char *p = s; *p; p++) {
        switch (*p) {
            case '<':  fputs("&lt;", out); break;
            case '>':  fputs("&gt;", out); break;
            case '&':  fputs("&amp;", out); break;
            case '"':  fputs("&quot;", out); break;
            default:   fputc(*p, out); break;
        }
    }
}

/* Output a field with control-char caret escaping (default behavior). */
static void listOutputField(FILE *out, const char *s) {
    for (const char *p = s; *p; p++) {
        unsigned char c = (unsigned char)*p;
        if (c < 0x20 && c != '\t') {
            fputc('^', out);
            fputc('@' + c, out);
        } else if (c == 0x7f) {
            fputs("^?", out);
        } else {
            fputc(c, out);
        }
    }
}

/* Format a numeric value like sqlite3 does (text as-is, but handle float) */
static void formatColumn(ShellState *p, FILE *out, sqlite3_stmt *stmt, int col) {
    int type = sqlite3_column_type(stmt, col);
    if (type == SQLITE_NULL) {
        switch (p->mode) {
            case MODE_CSV:
                break;  /* empty field */
            case MODE_HTML:
                break;
            default:
                fputs(p->nullValue, out);
                break;
        }
        return;
    }
    const unsigned char *txt = sqlite3_column_text(stmt, col);
    const char *s = (const char*)(txt ? txt : (const unsigned char*)"");
    switch (p->mode) {
        case MODE_CSV:
            csvOutputField(out, s, p->colSep);
            break;
        case MODE_HTML:
            htmlOutputField(out, s);
            break;
        case MODE_TABS:
            fputs(s, out);
            break;
        default:
            listOutputField(out, s);
            break;
    }
}

static void printRow(ShellState *p, FILE *out, sqlite3_stmt *stmt,
                     int *pHeaderPrinted) {
    int ncols = sqlite3_column_count(stmt);
    int i;
    if (ncols <= 0) return;

    if (p->mode == MODE_LINE) {
        /* Find max header width for alignment */
        int maxw = 0;
        for (i = 0; i < ncols; i++) {
            int n = (int)strlen(sqlite3_column_name(stmt, i));
            if (n > maxw) maxw = n;
        }
        if (*pHeaderPrinted) fputc('\n', out);
        for (i = 0; i < ncols; i++) {
            int type = sqlite3_column_type(stmt, i);
            const unsigned char *txt = sqlite3_column_text(stmt, i);
            const char *s = (type == SQLITE_NULL) ? p->nullValue
                                                  : (const char*)(txt?txt:(const unsigned char*)"");
            fprintf(out, "%*s = %s\n", maxw,
                    sqlite3_column_name(stmt, i), s);
        }
        *pHeaderPrinted = 1;
        return;
    }

    if (p->mode == MODE_HTML) {
        if (!*pHeaderPrinted && p->showHeader) {
            fputs("<TR>\n", out);
            for (i = 0; i < ncols; i++) {
                fputs("<TH>", out);
                htmlOutputField(out, sqlite3_column_name(stmt, i));
                fputc('\n', out);
            }
            fputs("</TR>\n", out);
            *pHeaderPrinted = 1;
        }
        fputs("<TR>\n", out);
        for (i = 0; i < ncols; i++) {
            fputs("<TD>", out);
            formatColumn(p, out, stmt, i);
            fputc('\n', out);
        }
        fputs("</TR>\n", out);
        return;
    }

    /* Headers for list/csv/tabs modes */
    if (!*pHeaderPrinted && p->showHeader) {
        for (i = 0; i < ncols; i++) {
            if (i > 0) {
                const char *sep = (p->mode == MODE_TABS) ? "\t"
                                : (p->mode == MODE_CSV)  ? ","
                                : p->colSep;
                fputs(sep, out);
            }
            if (p->mode == MODE_CSV) {
                csvOutputField(out, sqlite3_column_name(stmt, i), ",");
            } else {
                listOutputField(out, sqlite3_column_name(stmt, i));
            }
        }
        fputs(p->rowSep, out);
        *pHeaderPrinted = 1;
    }

    for (i = 0; i < ncols; i++) {
        if (i > 0) {
            const char *sep = (p->mode == MODE_TABS) ? "\t"
                            : (p->mode == MODE_CSV)  ? ","
                            : p->colSep;
            fputs(sep, out);
        }
        formatColumn(p, out, stmt, i);
    }
    fputs(p->rowSep, out);
}

/* Run a single batch of SQL, possibly containing multiple statements. */
static int runSql(ShellState *p, sqlite3 *db, const char *sql,
                  int argIndex, int isCmdline)
{
    const char *zLeftover;
    const char *zCur = sql;
    int rc = SQLITE_OK;
    int result = 0;

    while (*zCur) {
        /* skip whitespace */
        while (*zCur && isspace((unsigned char)*zCur)) zCur++;
        if (!*zCur) break;
        sqlite3_stmt *stmt = NULL;
        rc = sqlite3_prepare_v2(db, zCur, -1, &stmt, &zLeftover);
        if (rc != SQLITE_OK) {
            /* Build the offending SQL snippet (up to first semicolon or end) */
            const char *end = zCur;
            while (*end && *end != '\n') end++;
            char *snip = strndup(zCur, end - zCur);
            outputSqlError(p, db, snip, argIndex, isCmdline);
            free(snip);
            if (stmt) sqlite3_finalize(stmt);
            result = 1;
            if (p->bail) return 1;
            return result;
        }
        if (!stmt) { zCur = zLeftover; continue; }

        int headerPrinted = 0;
        while ((rc = sqlite3_step(stmt)) == SQLITE_ROW) {
            printRow(p, stdout, stmt, &headerPrinted);
        }
        if (rc != SQLITE_DONE) {
            const char *end = zCur;
            while (*end && *end != '\n' && *end != ';') end++;
            char *snip = strndup(zCur, end - zCur);
            outputSqlError(p, db, snip, argIndex, isCmdline);
            free(snip);
            sqlite3_finalize(stmt);
            result = 1;
            if (p->bail) return 1;
            zCur = zLeftover;
            continue;
        }
        sqlite3_finalize(stmt);
        zCur = zLeftover;
    }
    return result;
}

/* Read all of stdin into a buffer */
static char *slurpStdin(void) {
    size_t cap = 4096, len = 0;
    char *buf = malloc(cap);
    if (!buf) return NULL;
    int c;
    while ((c = fgetc(stdin)) != EOF) {
        if (len + 1 >= cap) {
            cap *= 2;
            buf = realloc(buf, cap);
            if (!buf) return NULL;
        }
        buf[len++] = (char)c;
    }
    buf[len] = 0;
    return buf;
}

/* Translate a separator escape like \n, \t into actual char. */
static void translateSeparator(char *dst, const char *src, size_t maxlen) {
    size_t i = 0, j = 0;
    while (src[i] && j + 1 < maxlen) {
        if (src[i] == '\\' && src[i+1]) {
            switch (src[i+1]) {
                case 'n': dst[j++] = '\n'; i += 2; break;
                case 't': dst[j++] = '\t'; i += 2; break;
                case 'r': dst[j++] = '\r'; i += 2; break;
                case '\\':dst[j++] = '\\'; i += 2; break;
                default:  dst[j++] = src[i++]; break;
            }
        } else {
            dst[j++] = src[i++];
        }
    }
    dst[j] = 0;
}

static int needsArg(const char *opt) {
    static const char *withArg[] = {
        "-cmd", "-init", "-nullvalue", "-separator", "-newline",
        "-vfs", "-mmap", "-maxsize", "-nonce", "-escape",
        "-screenwidth", NULL
    };
    for (int i = 0; withArg[i]; i++) {
        if (!strcmp(opt, withArg[i])) return 1;
    }
    /* two-arg options: lookaside, pagecache (SIZE N) */
    return 0;
}

static int needsTwoArgs(const char *opt) {
    if (!strcmp(opt, "-lookaside")) return 1;
    if (!strcmp(opt, "-pagecache")) return 1;
    return 0;
}

/* Known zero-arg options (including mode-setting ones) */
static int isKnownZeroArg(const char *opt) {
    static const char *zero[] = {
        "-append", "-ascii", "-bail", "-batch", "-box", "-column",
        "-csv", "-deserialize", "-echo", "-header", "-noheader",
        "-help", "-html", "-ifexists", "-interactive", "-json",
        "-line", "-list", "-markdown", "-memtrace", "-nofollow",
        "-noinit", "-no-rowid-in-view", "-pcachetrace", "-quote",
        "-readonly", "-safe", "-stats", "-table", "-tabs",
        "-unsafe-testing", "-version", "-vfstrace", "-zip", NULL
    };
    for (int i = 0; zero[i]; i++) {
        if (!strcmp(opt, zero[i])) return 1;
    }
    return 0;
}

int main(int argc, char **argv) {
    ShellState st;
    initShell(&st);
    st.progName = argv[0];

    /* Collect options and positional args. */
    char *dbfile = NULL;
    char **sqlArgs = calloc(argc, sizeof(char*));
    int *sqlArgIdx = calloc(argc, sizeof(int));
    int nSqlArgs = 0;
    int readStdin = !isatty(fileno(stdin));

    int i;
    int endOfOpts = 0;

    /* First pass: handle -version and -help, collect options. */
    for (i = 1; i < argc; i++) {
        char *a = argv[i];
        if (!endOfOpts && a[0] == '-') {
            /* Accept double-dash prefix */
            const char *opt = a;
            if (a[1] == '-' && a[2] != 0) {
                opt = a + 1;  /* skip one dash, keep second */
            }
            if (!strcmp(opt, "--")) {
                endOfOpts = 1;
                continue;
            }
            if (!strcmp(opt, "-version")) {
                fputs(kVersionString, stdout);
                return 0;
            }
            if (!strcmp(opt, "-help")) {
                printf(kHelpText, argv[0]);
                return 0;
            }
            if (!strcmp(opt, "-A")) {
                /* -A ARGS... -> archive (not implemented), swallow rest */
                return 0;
            }
            if (!strcmp(opt, "-header")) { st.showHeader = 1; continue; }
            if (!strcmp(opt, "-noheader")){ st.showHeader = 0; continue; }
            if (!strcmp(opt, "-bail"))   { st.bail = 1; continue; }
            if (!strcmp(opt, "-echo"))   { st.echo = 1; continue; }
            if (!strcmp(opt, "-batch")
             || !strcmp(opt, "-interactive")
             || !strcmp(opt, "-noinit")
             || !strcmp(opt, "-nofollow")
             || !strcmp(opt, "-readonly")
             || !strcmp(opt, "-append")
             || !strcmp(opt, "-deserialize")
             || !strcmp(opt, "-ifexists")
             || !strcmp(opt, "-memtrace")
             || !strcmp(opt, "-pcachetrace")
             || !strcmp(opt, "-stats")
             || !strcmp(opt, "-vfstrace")
             || !strcmp(opt, "-zip")
             || !strcmp(opt, "-safe")
             || !strcmp(opt, "-unsafe-testing")
             || !strcmp(opt, "-no-rowid-in-view"))
            {
                continue;
            }
            if (!strcmp(opt, "-ascii"))   { st.mode = MODE_ASCII; strcpy(st.colSep,"\x1f"); strcpy(st.rowSep,"\x1e"); continue; }
            if (!strcmp(opt, "-box"))     { st.mode = MODE_BOX;    continue; }
            if (!strcmp(opt, "-column"))  { st.mode = MODE_COLUMN; continue; }
            if (!strcmp(opt, "-csv"))     { st.mode = MODE_CSV;    strcpy(st.colSep,","); continue; }
            if (!strcmp(opt, "-html"))    { st.mode = MODE_HTML;   continue; }
            if (!strcmp(opt, "-json"))    { st.mode = MODE_JSON;   continue; }
            if (!strcmp(opt, "-line"))    { st.mode = MODE_LINE;   continue; }
            if (!strcmp(opt, "-list"))    { st.mode = MODE_LIST;   continue; }
            if (!strcmp(opt, "-markdown")){ st.mode = MODE_MARKDOWN; continue; }
            if (!strcmp(opt, "-quote"))   { st.mode = MODE_QUOTE;  continue; }
            if (!strcmp(opt, "-table"))   { st.mode = MODE_TABLE;  continue; }
            if (!strcmp(opt, "-tabs"))    { st.mode = MODE_TABS;   strcpy(st.colSep,"\t"); continue; }
            if (needsArg(opt)) {
                if (i + 1 >= argc) {
                    fprintf(stderr, "%s: Error: missing argument to %s\n",
                            argv[0], a);
                    return 1;
                }
                char *val = argv[++i];
                if (!strcmp(opt, "-separator")) {
                    translateSeparator(st.colSep, val, sizeof(st.colSep));
                } else if (!strcmp(opt, "-newline")) {
                    translateSeparator(st.rowSep, val, sizeof(st.rowSep));
                } else if (!strcmp(opt, "-nullvalue")) {
                    strncpy(st.nullValue, val, sizeof(st.nullValue)-1);
                    st.nullValue[sizeof(st.nullValue)-1] = 0;
                } else if (!strcmp(opt, "-cmd")) {
                    /* TODO: run as initial command (not implemented) */
                } else {
                    /* discard the value */
                }
                continue;
            }
            if (needsTwoArgs(opt)) {
                if (i + 2 >= argc) {
                    fprintf(stderr, "%s: Error: missing argument to %s\n",
                            argv[0], a);
                    return 1;
                }
                i += 2;
                continue;
            }
            if (isKnownZeroArg(opt)) continue;
            fprintf(stderr, "%s: Error: unknown option: %s\n", argv[0], a);
            fprintf(stderr, "Use -help for a list of options.\n");
            return 1;
        }
        /* Positional argument */
        if (!dbfile) {
            dbfile = a;
        } else {
            sqlArgs[nSqlArgs] = a;
            sqlArgIdx[nSqlArgs] = i + 1; /* 1-based for ordinal */
            nSqlArgs++;
        }
    }

    /* Open the database */
    sqlite3 *db = NULL;
    const char *openName = dbfile ? dbfile : ":memory:";
    if (sqlite3_open(openName, &db) != SQLITE_OK) {
        fprintf(stderr, "Error: unable to open database \"%s\": %s\n",
                openName, sqlite3_errmsg(db));
        if (db) sqlite3_close(db);
        return 1;
    }

    int exitCode = 0;

    /* Run SQL command-line arguments */
    for (int k = 0; k < nSqlArgs; k++) {
        if (st.echo) { fputs(sqlArgs[k], stdout); fputc('\n', stdout); }
        int rc = runSql(&st, db, sqlArgs[k], sqlArgIdx[k], 1);
        if (rc) { exitCode = rc; if (st.bail) break; }
    }

    /* If no SQL args, read from stdin when it's piped */
    if (nSqlArgs == 0 && readStdin) {
        char *input = slurpStdin();
        if (input) {
